import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.CpZKh-tG.js";const u=JSON.parse('{"title":"/fly Manual Test Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"reference/fly-manual-test-checklist.md","filePath":"reference/fly-manual-test-checklist.md"}'),o={name:"reference/fly-manual-test-checklist.md"};function r(l,e,n,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="fly-manual-test-checklist" tabindex="-1"><code>/fly</code> Manual Test Checklist <a class="header-anchor" href="#fly-manual-test-checklist" aria-label="Permalink to &quot;`/fly` Manual Test Checklist&quot;">​</a></h1><p>A walk-through of representative missions to exercise every code path in the heliocentric + cislunar /fly scenes. Use this as the manual smoke test after any /fly change, and as the reference spec for the future automated e2e equivalent.</p><p>The checklist was first executed on <strong>2026-06-09</strong> after the cinematic camera + FD stage marker rework (commit <code>7a8d8e* → main</code>). Results + known-broken items at the bottom.</p><hr><h2 id="how-to-drive-it" tabindex="-1">How to drive it <a class="header-anchor" href="#how-to-drive-it" aria-label="Permalink to &quot;How to drive it&quot;">​</a></h2><ol><li><code>npm run dev</code> (vite preview on <code>localhost:5273</code>).</li><li>Open Chrome DevTools MCP or just use a regular browser tab.</li><li>For each mission below, open the URL, scrub the timeline slider to the listed checkpoints, and verify the expectations.</li><li>Open the browser console — every test below expects <strong>zero</strong> error or warn messages.</li></ol><p>Useful one-liners (paste into DevTools console):</p><ul><li>Count revealed FD chips: <code>document.querySelectorAll(&#39;[data-testid=&quot;fd-phase-marker&quot;]&#39;).length</code></li><li>List revealed chip labels in order: <code>Array.from(document.querySelectorAll(&#39;[data-fd-phase]&#39;)).map(e=&gt;e.dataset.fdPhase)</code></li><li>Jump the scrubber to a given progress (0..1):<div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">querySelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;input[type=&quot;range&quot;]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Object.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getOwnPropertyDescriptor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HTMLInputElement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">prototype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;value&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).set;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">set.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(s, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0.75&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); s.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispatchEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;input&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { bubbles: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }));</span></span></code></pre></div></li></ul><hr><h2 id="test-cases" tabindex="-1">Test cases <a class="header-anchor" href="#test-cases" aria-label="Permalink to &quot;Test cases&quot;">​</a></h2><h3 id="a-round-trip-heliocentric-—-orrery-1-demo" tabindex="-1">A. Round-trip heliocentric — <code>ORRERY-1 demo</code> <a class="header-anchor" href="#a-round-trip-heliocentric-—-orrery-1-demo" aria-label="Permalink to &quot;A. Round-trip heliocentric — `ORRERY-1 demo`&quot;">​</a></h3><p>URL: <code>/fly</code> (no params). Trajectory: Heliocentric free-return Mars flyby. arr_day = 509.</p><p>Expectations:</p><ul><li>3D scene renders Sun at centre with both Earth + Mars orbits visible.</li><li>Three anchor rings: <ul><li>LAUNCH (blue, &quot;Earth dep&quot;) at outPts[0].</li><li>ARRIVAL (red, &quot;Mars arrival&quot;) at outPts[last].</li><li>RETURN (blue, &quot;Earth arrival&quot;) at retPts[last].</li></ul></li><li>FD chips on the arc, revealing on schedule:<table tabindex="0"><thead><tr><th>scrubber</th><th>revealed</th><th>notes</th></tr></thead><tbody><tr><td>0.0</td><td><code>Injection</code></td><td>tiny window before CRUISE threshold (0.03)</td></tr><tr><td>0.05</td><td><code>Injection</code>, <code>Cruise</code></td><td>CRUISE just past INJECTION</td></tr><tr><td>0.45</td><td><code>Injection</code>, <code>Cruise</code></td><td>mid-outbound</td></tr><tr><td>0.50</td><td><code>Injection</code>, <code>Cruise</code>, <code>Approach</code></td><td>outbound APPROACH fires</td></tr><tr><td>0.55</td><td><code>Injection</code>, <code>Cruise</code>, <code>Approach</code>, <code>Arrival</code></td><td>Mars-ARRIVAL fires</td></tr><tr><td>0.70</td><td>+ <code>Cruise</code> (return)</td><td>return CRUISE fires after Mars flyby</td></tr><tr><td>0.92</td><td>+ <code>Approach</code> (Earth)</td><td>return APPROACH fires</td></tr><tr><td>0.99</td><td>+ <code>Arrival</code> (Earth)</td><td>all 7 stages revealed</td></tr></tbody></table></li><li>Camera arc: <ul><li>t=0: tight on Earth (~30u).</li><li>Slow LERP into wide cruise; Sun visible, ship tracked.</li><li>Approach-Mars (~outboundT 0.8): closeup on Mars destination.</li><li>Mars-depart (returnT &lt; 0.05): held shot tracking ship as it leaves Mars.</li><li>Earth-approach (~returnT 0.9): closeup on Earth.</li></ul></li><li>FlightDirectorBanner phase eyebrow cycles through <code>INJECTION</code> → <code>CRUISE</code> → <code>APPROACH</code> → <code>ARRIVAL</code> → <code>CRUISE</code> → <code>APPROACH</code> → <code>ARRIVAL</code>.</li><li>No console errors.</li></ul><h3 id="b-one-way-mars-surface-—-curiosity" tabindex="-1">B. One-way Mars surface — <code>curiosity</code> <a class="header-anchor" href="#b-one-way-mars-surface-—-curiosity" aria-label="Permalink to &quot;B. One-way Mars surface — `curiosity`&quot;">​</a></h3><p>URL: <code>/fly?mission=curiosity</code>. Trajectory: Heliocentric Hohmann. dep=2011-11-26, arr=2012-08-06.</p><p>Expectations:</p><ul><li>LAUNCH ring (blue) at Earth-at-dep; ARRIVAL ring at Mars-at-arr.</li><li>ARRIVAL ring subtitle uses <code>mission.arr_label</code> directly (&quot;2012-08-06&quot;), NOT the destination-aware override (that only triggers on round-trip).</li><li><strong>No RETURN ring</strong> (retPts.length === 0).</li><li>FD chips:<table tabindex="0"><thead><tr><th>scrubber</th><th>revealed</th></tr></thead><tbody><tr><td>0.05</td><td><code>Injection</code>, <code>Cruise</code></td></tr><tr><td>0.5</td><td><code>Injection</code>, <code>Cruise</code></td></tr><tr><td>0.85</td><td>+ <code>Approach</code></td></tr><tr><td>0.97</td><td>+ <code>Arrival</code></td></tr></tbody></table></li><li>FD banner cycles only <code>INJECTION</code> → <code>CRUISE</code> → <code>APPROACH</code> → <code>ARRIVAL</code> (never enters the return-leg branch).</li><li>No console errors.</li></ul><h3 id="c-round-trip-asteroid-sample-return-—-hayabusa2" tabindex="-1">C. Round-trip asteroid sample-return — <code>hayabusa2</code> <a class="header-anchor" href="#c-round-trip-asteroid-sample-return-—-hayabusa2" aria-label="Permalink to &quot;C. Round-trip asteroid sample-return — `hayabusa2`&quot;">​</a></h3><p>URL: <code>/fly?mission=hayabusa2</code>. Trajectory: H-IIA → Ryugu rendezvous + sample return.</p><p>Expectations:</p><ul><li>LAUNCH (blue) at Earth-at-dep, ARRIVAL ring positioned at the destination (asteroid), with subtitle <code>Asteroid arrival</code> (the destination-aware override for round-trip).</li><li>RETURN ring (blue) at retPts[last] with subtitle <code>Earth arrival</code>.</li><li>Full 7-stage FD chain reveals across timeline.</li><li>Approach-Earth on return uses <code>HELIO_EARTH_CLOSEUP_R=50</code> (looser Earth zoom than destination-side <code>HELIO_CLOSEUP_R=40</code>).</li><li>No console errors.</li></ul><h3 id="d-outer-system-one-way-jupiter-saturn-range-—-voyager-1" tabindex="-1">D. Outer-system one-way (Jupiter / Saturn range) — <code>voyager-1</code> <a class="header-anchor" href="#d-outer-system-one-way-jupiter-saturn-range-—-voyager-1" aria-label="Permalink to &quot;D. Outer-system one-way (Jupiter / Saturn range) — `voyager-1`&quot;">​</a></h3><p>URL: <code>/fly?mission=voyager-1</code>. Destination: Saturn (9.5 AU).</p><p>Expectations:</p><ul><li>3D scene renders Sun + Earth orbit + Saturn orbit, all visible at the wider <code>cameraDistanceFor(SATURN) = max(180, 9.5·80·2) = 1520u</code>.</li><li>4 outbound FD chips reveal as scrubber moves through 0 → 1.</li><li>No RETURN ring (one-way).</li><li>Long cruise gives the steady-cam azimuthal drift (0.05 rad/s) time to read — camera should slowly orbit the spacecraft.</li><li>No console errors.</li></ul><h3 id="e1-one-way-moon-—-slim" tabindex="-1">E1. One-way Moon — <code>slim</code> <a class="header-anchor" href="#e1-one-way-moon-—-slim" aria-label="Permalink to &quot;E1. One-way Moon — `slim`&quot;">​</a></h3><p>URL: <code>/fly?mission=slim</code>.</p><p>Expectations (cislunar one-way):</p><ul><li>Cislunar scene active.</li><li><code>helioFd === 0</code> (FD diamonds gated out).</li><li><code>cislunarMarkers === 1</code>.</li><li>ARRIVAL event at MET 110 — no EARTH RETURN. retPts.length === 0.</li><li>No console errors.</li></ul><h3 id="e-moon-cislunar-—-apollo11" tabindex="-1">E. Moon cislunar — <code>apollo11</code> <a class="header-anchor" href="#e-moon-cislunar-—-apollo11" aria-label="Permalink to &quot;E. Moon cislunar — `apollo11`&quot;">​</a></h3><p>URL: <code>/fly?mission=apollo11</code>.</p><p>Expectations:</p><ul><li>Cislunar scene active (Earth-centred, Moon orbits at exaggerated scale).</li><li><strong>Helio FD diamonds do NOT render</strong> (gated by <code>viewMode === &#39;heliocentric&#39;</code>). <ul><li>DOM check: <code>document.querySelectorAll(&#39;[data-testid=&quot;fd-phase-marker&quot;]&#39;).length === 0</code>.</li></ul></li><li>Cislunar phase markers DO render (separate pipeline). <ul><li>DOM check: <code>document.querySelectorAll(&#39;[data-testid=&quot;phase-markers-overlay&quot;]&#39;).length === 1</code>.</li></ul></li><li>Apollo timeline events visible in CAPCOM panel (LAUNCH / TLI / LOI / TEI / EARTH RETURN).</li><li>No console errors.</li></ul><h3 id="f1-modern-lunar-round-trip-—-artemis3" tabindex="-1">F1. Modern lunar round-trip — <code>artemis3</code> <a class="header-anchor" href="#f1-modern-lunar-round-trip-—-artemis3" aria-label="Permalink to &quot;F1. Modern lunar round-trip — `artemis3`&quot;">​</a></h3><p>URL: <code>/fly?mission=artemis3</code>.</p><p>Expectations:</p><ul><li>Cislunar scene active (same path as Apollo 11).</li><li>helioFd === 0, cislunarMarkers === 1.</li><li>Events span LAUNCH → TLI → TCM → ASCENT → TEI → EARTH RETURN — full SLS/Starship crew-and-return cadence.</li><li>No console errors.</li></ul><h3 id="f-cislunar-free-return-—-apollo13" tabindex="-1">F. Cislunar free-return — <code>apollo13</code> <a class="header-anchor" href="#f-cislunar-free-return-—-apollo13" aria-label="Permalink to &quot;F. Cislunar free-return — `apollo13`&quot;">​</a></h3><p>URL: <code>/fly?mission=apollo13</code>.</p><p>Expectations:</p><ul><li>Cislunar scene active. Same constraints as Apollo 11 (no helio FD, yes cislunar phase markers).</li><li>Free-return arc visible.</li><li>CAPCOM panel surfaces the anomaly event.</li><li>No console errors.</li></ul><hr><h2 id="bonus-checks-do-these-manually-on-at-least-one-round-trip-mission" tabindex="-1">Bonus checks (do these manually on at least one round-trip mission) <a class="header-anchor" href="#bonus-checks-do-these-manually-on-at-least-one-round-trip-mission" aria-label="Permalink to &quot;Bonus checks (do these manually on at least one round-trip mission)&quot;">​</a></h2><ul><li>Toggle Science Lens <strong>on</strong>. The top-centre Science Lens panel must sit directly under the nav header (NOT in the canvas centre — that regression was caused by <code>FlightDirectorBanner</code> publishing its height to <code>--lens-banner-height</code> while sitting in the bottom strip).</li><li>Toggle the timeline <code>Pause</code> / <code>Play</code> button. Camera lerps should pause / resume cleanly.</li><li>Drag the canvas to orbit the camera; release. Steady-cam drift should stop on drag and resume after.</li><li>Pinch-zoom (or wheel-zoom). User-zoom should override the auto-zoom for the rest of the sub-phase.</li><li>Reload with <code>prefers-reduced-motion: reduce</code>. Camera drift + fd-marker pop animation should disable.</li></ul><hr><h2 id="g-flyby-cinema-—-voyager-2-and-other-grand-tour-missions" tabindex="-1">G. Flyby Cinema — <code>voyager-2</code> (and other grand-tour missions) <a class="header-anchor" href="#g-flyby-cinema-—-voyager-2-and-other-grand-tour-missions" aria-label="Permalink to &quot;G. Flyby Cinema — `voyager-2` (and other grand-tour missions)&quot;">​</a></h2><p>URL: <code>/fly?mission=voyager-2</code>. Mission events include 4 <code>flyby</code> entries: Jupiter (MET 688), Saturn (MET 1466), Uranus (MET 3079), Neptune (MET 4388).</p><p>Expectations (per flyby):</p><ul><li>When <code>|simDay − dep_day − met_days| ≤ 25</code>, the camera enters a dedicated <code>flyby-&lt;met&gt;</code> sub-phase.</li><li>Sub-phase: closeup framing (<code>HELIO_FLYBY_R = 80u</code>) centred on the live spacecraft scene position with approach-pitch tilt.</li><li>Sun visible in frame (since spacecraft is at heliocentric position of the flyby planet, ~5–30 AU from origin).</li><li>Smooth LERP in / out of the closeup as the window opens + closes.</li><li>Outside the window, regular cruise / approach sub-phases run.</li></ul><p>How to drive:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Jupiter flyby at MET 688 of 4388 total → slider ≈ 688/4388 = 0.157</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">querySelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;input[type=&quot;range&quot;]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Object.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getOwnPropertyDescriptor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HTMLInputElement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">prototype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;value&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).set;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">set.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(s, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0.157&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); s.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispatchEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;input&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { bubbles: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }));</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Pause via the Pause button, then wait a few seconds for camera lerp.</span></span></code></pre></div><p>Same pattern is data-driven: it auto-activates for any mission whose <code>flight.events[]</code> includes one or more <code>type: &#39;flyby&#39;</code> entries. Tally from a 2026-06-09 grep across mission JSON files:</p><table tabindex="0"><thead><tr><th>Mission</th><th>Destination</th><th>Flybys</th><th>Cinema value</th></tr></thead><tbody><tr><td><code>bepicolombo</code></td><td>Mercury</td><td>9</td><td>🏆 highest</td></tr><tr><td><code>messenger</code></td><td>Mercury</td><td>6</td><td>high</td></tr><tr><td><code>rosetta</code></td><td>Comet</td><td>6</td><td>high</td></tr><tr><td><code>galileo</code></td><td>Jupiter</td><td>5</td><td>high</td></tr><tr><td><code>cassini</code></td><td>Saturn</td><td>4</td><td>high (✓ verified)</td></tr><tr><td><code>voyager-2</code></td><td>Neptune</td><td>4</td><td>high (✓ verified)</td></tr><tr><td><code>juice</code></td><td>Jupiter</td><td>4</td><td>high</td></tr><tr><td><code>new-horizons</code></td><td>Pluto</td><td>3</td><td>mid</td></tr><tr><td><code>giotto</code></td><td>Comet</td><td>3</td><td>mid</td></tr><tr><td><code>voyager-1</code></td><td>Saturn</td><td>2</td><td>mid</td></tr><tr><td><code>pioneer-11</code></td><td>Saturn</td><td>2</td><td>mid</td></tr><tr><td><code>vega-1</code> / <code>vega-2</code></td><td>Venus</td><td>2</td><td>mid</td></tr><tr><td><code>pioneer-10</code>, <code>mariner4</code>, <code>ulysses</code>, <code>hayabusa2</code>, <code>dawn</code>, <code>juno</code></td><td>various</td><td>1</td><td>low (single arrival)</td></tr></tbody></table><p>Cassini Earth-flyby validation: scrubbing to MET 894 (slider ≈ 0.365) on a paused sim, then clicking the timeline &quot;FLYBY at MET 894.00 days&quot; jump button, drives the camera into a tight closeup that shows the spacecraft and the LAUNCH ring at Earth&#39;s position simultaneously.</p><hr><h2 id="h-milestone-overlay-—-labeled-flight-events" tabindex="-1">H. Milestone overlay — labeled <code>flight.events[]</code> <a class="header-anchor" href="#h-milestone-overlay-—-labeled-flight-events" aria-label="Permalink to &quot;H. Milestone overlay — labeled `flight.events[]`&quot;">​</a></h2><p>URL: <code>/fly?mission=cassini</code> (the first backfilled mission).</p><p>Expectations:</p><ul><li>Each <code>flight.events[]</code> entry that carries a <code>label</code> field renders as a small teal <code>◇ &lt;label&gt;</code> chip at the spacecraft&#39;s projected scene position at the event MET.</li><li>Distinct visual language from FD stage markers: teal vs gold, chip-with-leading-diamond vs chip-above-leader, no reveal gating (milestones always render once the event is on-screen).</li><li>DOM contract: <ul><li>Overlay container: <code>[data-testid=&quot;milestone-overlay&quot;]</code> with <code>data-milestone-count=&quot;&lt;N&gt;&quot;</code>.</li><li>Each chip: <code>[data-testid=&quot;milestone-chip&quot;]</code> with <code>data-met-days=&quot;&lt;met&gt;&quot;</code>, contains <code>.milestone-tick</code> (◇) + <code>.milestone-label</code> (text).</li></ul></li></ul><p>Driving Cassini through its milestone roster:</p><ul><li>Jump to MET 0 → &quot;◇ Launch&quot; near LAUNCH ring.</li><li>Jump to MET 207 → &quot;◇ Venus #1 — gravity assist&quot; at the spacecraft.</li><li>Jump to MET 808 / 894 / 2226 → Venus #2 / Earth / Jupiter chips.</li><li>Jump to MET 2451 → &quot;◇ Saturn orbit insertion&quot; at Saturn.</li></ul><p>Iconic-mission backfill status (2026-06-09):</p><ul><li>✅ Cassini (6 milestones)</li><li>⏳ All 17 other iconic missions still anonymous — backfill is a mechanical pass joining <code>/static/data/trajectories/&lt;id&gt;.json</code> waypoints to <code>/static/data/missions/&lt;dest&gt;/&lt;id&gt;.json</code> events by date. Tracked as a follow-up data migration.</li></ul><hr><h2 id="round-2-changes-2026-06-09" tabindex="-1">Round-2 changes (2026-06-09) <a class="header-anchor" href="#round-2-changes-2026-06-09" aria-label="Permalink to &quot;Round-2 changes (2026-06-09)&quot;">​</a></h2><p>These are the broken items from the initial run that have been fixed or addressed in this same session:</p><ol><li><p><strong>Helio camera far-plane was 4000u, clipping Neptune + Pluto. FIXED.</strong></p><ul><li>Bumped <code>PerspectiveCamera.far</code> from 4000 → 16000 in <code>src/lib/three/fly-helio-scene.ts</code>.</li><li>Also capped <code>cameraDistanceFor</code> at 1600u (Saturn-scale wide) in <code>src/lib/fly-scene-constants.ts</code> — Voyager 2 / Pluto missions keep the Saturn-level framing and the spacecraft simply flies off the wide-frame edge during cruise, approached only when the flyby cinema sub-phase zooms in on it.</li><li>Outer-system visual readability is still poor (Sun + orbit rings read as small at 1600u framing) — that&#39;s a separate LOD-scaling UX pass beyond this fix.</li></ul></li><li><p><strong><code>Hayabusa 2</code> mission data clipped to primary Earth-return. FIXED.</strong></p><ul><li>Removed the extended-cruise events at MET 4250 + 6092 from <code>static/data/missions/asteroid/hayabusa2.json</code>.</li><li>The visible mission events now stop at MET 1880 (sample-return capsule reentry over Woomera).</li><li>Note: a full mission-length clip would require an <code>end_met_days</code> architectural addition (transit_days × 2 is still the round-trip total length internally). Filed as a follow-up.</li></ul></li><li><p><strong>One-way Moon-mode coverage added.</strong> See test E1 (SLIM) above.</p></li><li><p><strong>Flyby Cinema mode added</strong> for grand-tour missions. See test G.</p></li></ol><hr><h2 id="still-to-fix-next-carry-forward" tabindex="-1">Still to-fix-next (carry forward) <a class="header-anchor" href="#still-to-fix-next-carry-forward" aria-label="Permalink to &quot;Still to-fix-next (carry forward)&quot;">​</a></h2><ol><li><p><strong>Outer-system visual LOD.</strong> With <code>cameraDistanceFor</code> capped at 1600u and the camera framing wide, the Sun (8u radius) projects to a few pixels and the orbit rings disappear into the background. A distance-aware scale-up (or LOD swap) for the Sun mesh + orbit line widths would make outer-system framings actually readable.</p></li><li><p><strong><code>end_met_days</code> override field on missions.</strong> Hayabusa 2 needs to end at MET 1880 (Earth return), but the scrubber still spans the round-trip-derived 2604 days. Adding an explicit <code>flight.end_met_days</code> field would let mission data clip the timeline without abusing <code>transit_days</code>.</p></li><li><p><strong>Flyby planet meshes.</strong> The flyby cinema sub-phase zooms close on the spacecraft, but the flyby body (Jupiter, Saturn, etc.) isn&#39;t rendered as a textured sphere — only the active destination is. Rendering all bodies on the trajectory&#39;s flyby roster would complete the &quot;mini-movie&quot; feel by giving the camera a planet to look at during the flyby beat.</p></li></ol><hr><h2 id="suggested-next-iteration-of-this-doc" tabindex="-1">Suggested next iteration of this doc <a class="header-anchor" href="#suggested-next-iteration-of-this-doc" aria-label="Permalink to &quot;Suggested next iteration of this doc&quot;">​</a></h2><ul><li>Convert the per-mission scrubber tables into a Playwright spec (<code>tests/e2e/fly-stages.spec.ts</code>) using the same chip-reveal DOM selectors. Each row in the table → one <code>expect(...).toHaveText(...)</code>.</li><li>Add a programmatic &quot;no console errors&quot; assertion via <code>page.on(&#39;console&#39;)</code>.</li><li>Render the test plan inline at the bottom of <code>tests/e2e/_helpers/fly.ts</code> so contributors find it without leaving the spec.</li></ul><hr><p><em>Last manually executed: 2026-06-09 — Marko + Claude (Opus 4.7 · 1M context).</em></p>',76)])])}const y=t(o,[["render",r]]);export{u as __pageData,y as default};
